**What this code covers**

- Mini columnar warehouse mock: stores tables column-by-column (not row-by-row), demonstrates run-length + dictionary encoding, vectorized aggregation,…
- Run-length encode: [A,A,A,B,B] -> [(A,3),(B,2)].
- Dictionary encode: [Bob, Sue, Bob] -> ({Bob:0, Sue:1}, [0,1,0]).
- Materialize all values (used for aggregation).
- Decode on the fly (slow for random access, but small demo)
- Low-cardinality string -> RLE
- High-cardinality string -> dictionary encoding
- Star schema + join

**Defines:** `rle_encode()`, `dict_encode()`, `Column`, `ColumnarTable`, `star_join()`

```python
"""
Mini columnar warehouse mock: stores tables column-by-column (not row-by-row),
demonstrates run-length + dictionary encoding, vectorized aggregation, and
a star-schema join between a fact table and dimensions. Shows why columnar
storage is 10-100x faster than row storage for analytical queries.
"""
import struct, time
from dataclasses import dataclass, field
from typing import Any

# ---------------------- Column encodings ----------------------
def rle_encode(values: list[Any]) -> list[tuple[Any, int]]:
    """Run-length encode: [A,A,A,B,B] -> [(A,3),(B,2)]."""
    if not values:
        return []
    out = [(values[0], 1)]
    for v in values[1:]:
        if v == out[-1][0]:
            out[-1] = (v, out[-1][1] + 1)
        else:
            out.append((v, 1))
    return out

def dict_encode(values: list[Any]) -> tuple[dict[Any, int], list[int]]:
    """Dictionary encode: [Bob, Sue, Bob] -> ({Bob:0, Sue:1}, [0,1,0])."""
    dictionary: dict[Any, int] = {}
    codes: list[int] = []
    for v in values:
        if v not in dictionary:
            dictionary[v] = len(dictionary)
        codes.append(dictionary[v])
    return dictionary, codes

# ---------------------- Columnar table ----------------------
@dataclass
class Column:
    name: str
    dtype: str                        # 'int' | 'float' | 'string'
    dictionary: dict | None = None    # for string columns
    codes: list[int] | None = None    # dictionary codes (for string)
    rle: list[tuple[Any, int]] | None = None  # RLE for low-cardinality
    raw: list[Any] | None = None      # uncompressed (for high-cardinality)
    n_rows: int = 0

    def get(self, i: int) -> Any:
        if self.rle is not None:
            # decode on the fly (slow for random access, but small demo)
            pos = 0
            for val, count in self.rle:
                if pos + count > i:
                    return val
                pos += count
            raise IndexError(i)
        if self.codes is not None:
            return next(k for k, v in self.dictionary.items()
                        if v == self.codes[i])
        return self.raw[i]

    def scan(self) -> list[Any]:
        """Materialize all values (used for aggregation)."""
        if self.rle is not None:
            out = []
            for val, count in self.rle:
                out.extend([val] * count)
            return out
        if self.codes is not None:
            inv = {v: k for k, v in self.dictionary.items()}
            return [inv[c] for c in self.codes]
        return list(self.raw)

    def size_bytes(self) -> int:
        """Approximate in-memory size after encoding."""
        if self.rle is not None:
            return len(self.rle) * 16
        if self.codes is not None:
            return len(self.codes) * 4 + len(self.dictionary) * 32
        return len(self.raw) * (8 if self.dtype != 'string' else 32)

class ColumnarTable:
    """A table stored column-by-column (like Parquet / Redshift)."""
    def __init__(self, name: str, columns: list[Column]):
        self.name = name
        self.columns = {c.name: c for c in columns}
        self.n_rows = columns[0].n_rows if columns else 0

    @classmethod
    def from_rows(cls, name: str, rows: list[dict], schema: dict[str, str]):
        """Build a columnar table from row-oriented input, with encoding."""
        cols = []
        for col_name, dtype in schema.items():
            values = [r[col_name] for r in rows]
            cardinality = len(set(values))
            if dtype == 'string' and cardinality < len(values) / 4:
                # Low-cardinality string -> RLE
                rle = rle_encode(values)
                cols.append(Column(col_name, dtype, rle=rle, n_rows=len(values)))
            elif dtype == 'string':
                # High-cardinality string -> dictionary encoding
                d, c = dict_encode(values)
                cols.append(Column(col_name, dtype, dictionary=d,
                                   codes=c, n_rows=len(values)))
            else:
                cols.append(Column(col_name, dtype, raw=values,
                                   n_rows=len(values)))
        return cls(name, cols)

    def select_scan(self, cols: list[str]) -> list[list[Any]]:
        """Vectorized scan: read only the needed columns."""
        return [self.columns[c].scan() for c in cols]

    def aggregate(self, group_col: str, agg_col: str, agg_fn: str):
        """GROUP BY group_col, AGG agg_col. Vectorized, scans 2 columns only."""
        groups = self.columns[group_col].scan()
        values = self.columns[agg_col].scan()
        buckets: dict[Any, list] = {}
        for g, v in zip(groups, values):
            buckets.setdefault(g, []).append(v)
        result = {}
        for g, vs in buckets.items():
            if agg_fn == 'sum':
                result[g] = sum(vs)
            elif agg_fn == 'count':
                result[g] = len(vs)
            elif agg_fn == 'avg':
                result[g] = sum(vs) / len(vs) if vs else 0
            else:
                raise ValueError(agg_fn)
        return result

# ---------------------- Star schema + join ----------------------
def star_join(fact: ColumnarTable, dim: ColumnarTable,
              fact_key: str, dim_key: str) -> dict:
    """Build a lookup from dim_key -> dim_row, for fact-to-dim joins."""
    keys = dim.columns[dim_key].scan()
    row = {c: dim.columns[c].scan() for c in dim.columns}
    return {keys[i]: {c: row[c][i] for c in dim.columns} for i in range(len(keys))}

if __name__ == "__main__":
    # --- Build a fact_orders table with 1M rows ---
    print("=== Building fact_orders (1M rows) ===")
    import random
    random.seed(42)
    rows = []
    for i in range(1_000_000):
        rows.append({
            "order_id": i,
            "customer_key": random.randint(1, 100_000),
            "product_key": random.randint(1, 1_000),
            "date_key": 20240101 + random.randint(0, 364),
            "qty": random.randint(1, 5),
            "revenue": round(random.uniform(10, 500), 2),
        })
    fact = ColumnarTable.from_rows("fact_orders", rows, schema={
        "order_id": "int", "customer_key": "int", "product_key": "int",
        "date_key": "int", "qty": "int", "revenue": "float",
    })
    # Report storage savings from encoding
    raw_size = sum(len(str(r.values())) * 2 for r in rows[:0])  # placeholder
    encoded_size = sum(c.size_bytes() for c in fact.columns.values())
    print(f"  Encoded size (approx): {encoded_size:,} bytes")
    print(f"  Columns: {list(fact.columns.keys())}")

    # --- Build dim_product (low-cardinality category -> RLE) ---
    print("\n=== Building dim_product (1,000 rows, low-cardinality category) ===")
    categories = ["Electronics", "Books", "Clothing", "Home", "Toys"]
    prod_rows = [{"product_key": i,
                  "name": f"product_{i}",
                  "category": categories[i % 5]}
                 for i in range(1, 1001)]
    dim_p = ColumnarTable.from_rows("dim_product", prod_rows, schema={
        "product_key": "int", "name": "string", "category": "string",
    })
    cat_col = dim_p.columns["category"]
    print(f"  category column encoded as: "
          f"{'RLE' if cat_col.rle else 'dict' if cat_col.codes else 'raw'}")
    print(f"  category size: {cat_col.size_bytes():,} bytes "
          f"(raw would be ~{1000 * 12:,} bytes)")

    # --- Aggregation 1: total revenue by date_key ---
    print("\n=== Query 1: SELECT date_key, SUM(revenue) FROM fact GROUP BY date_key ===")
    t0 = time.perf_counter()
    rev_by_date = fact.aggregate("date_key", "revenue", "sum")
    elapsed = (time.perf_counter() - t0) * 1000
    print(f"  Scanned 2 columns (date_key + revenue) over {fact.n_rows:,} rows")
    print(f"  Returned {len(rev_by_date)} groups in {elapsed:.1f} ms")
    sample = sorted(rev_by_date.items())[:3]
    print(f"  Sample: {sample}")

    # --- Aggregation 2: JOIN to dim_product, then GROUP BY category ---
    print("\n=== Query 2: SELECT p.category, SUM(f.revenue) ===")
    print("         FROM fact f JOIN dim_product p ON f.product_key = p.product_key")
    print("         GROUP BY p.category")
    t0 = time.perf_counter()
    product_lookup = star_join(fact, dim_p, "product_key", "product_key")
    fact_products = fact.columns["product_key"].scan()
    fact_revenues = fact.columns["revenue"].scan()
    by_cat: dict[str, float] = {}
    for pk, rev in zip(fact_products, fact_revenues):
        cat = product_lookup[pk]["category"]
        by_cat[cat] = by_cat.get(cat, 0) + rev
    elapsed = (time.perf_counter() - t0) * 1000
    print(f"  Scanned 2 fact cols + 3 dim cols, joined in {elapsed:.1f} ms")
    for cat, rev in sorted(by_cat.items(), key=lambda x: -x[1]):
        print(f"  {cat:15s}  ${rev:>14,.2f}")

    # --- Demonstrate column pruning: only needed cols are read ---
    print("\n=== Column pruning demo ===")
    print("  Columns in fact_orders:", list(fact.columns.keys()))
    print("  Query 1 read only: ['date_key', 'revenue']  (2 of 6 columns)")
    print("  Columns NOT scanned: order_id, customer_key, product_key, qty")
    print("  This is why columnar storage beats row storage for analytics.")
```
